ls -la site/fonts; (npm start >$TMPDIR/s.log 2>&1 &); sleep 2; cat > $TMPDIR/shot.js <<'EOF'
const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch();for(const w of [1280,400]){const p=await b.newPage({viewport:{width:w,height:900}});
p.on('console',m=>console.log('console',m.text()));p.on('requestfailed',r=>console.log('fail',r.url()));
await p.goto(`http://127.0.0.1:${process.env.PORT}/pricing.html`);await p.screenshot({path:process.env.TMPDIR+`/p${w}.png`,fullPage:true});}
await b.close()})()
EOF
NODE_PATH=$PWD/node_modules node $TMPDIR/shot.js

